import { motion } from "framer-motion";
import "../App.css";

function Hero() {
  const fadeUp = {
    hidden: { opacity: 0, y: 40 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.8, ease: "easeOut" } },
  };

  const staggerContainer = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2,
      },
    },
  };

  return (
    <div>
      {/* ✅ Navbar 제거 완료 */}

      <main
        style={{
          minHeight: "100vh",
          background: "#0a0a0a",
          position: "relative",
          overflow: "hidden",
        }}
      >
        {/* Hero Section */}
        <motion.div
          style={{
            display: "grid",
            gridTemplateColumns: "1fr 1fr",
            gap: "100px",
            maxWidth: "1600px",
            margin: "0 auto",
            padding: "120px 80px 140px",
            alignItems: "center",
          }}
          initial="hidden"
          animate="visible"
          variants={staggerContainer}
        >
          {/* Left Content */}
          <motion.div variants={fadeUp}>
            <div
              style={{
                display: "inline-block",
                padding: "8px 20px",
                background: "rgba(255, 107, 53, 0.1)",
                border: "1px solid rgba(255, 107, 53, 0.2)",
                borderRadius: "30px",
                marginBottom: "40px",
              }}
            >
              <span
                style={{
                  fontSize: "13px",
                  fontWeight: "600",
                  color: "#ff6b35",
                  letterSpacing: "1px",
                  textTransform: "uppercase",
                }}
              >
                Professional Design Platform
              </span>
            </div>

            <h1
              style={{
                fontSize: "clamp(3rem, 5vw, 5.5rem)",
                fontWeight: 900,
                color: "#fff",
                marginBottom: "30px",
                lineHeight: "1.1",
                letterSpacing: "-2.5px",
              }}
            >
              AI-driven Interior
              <br />
              <span
                style={{
                  background: "linear-gradient(135deg, #ff6b35 0%, #ff4d00 100%)",
                  WebkitBackgroundClip: "text",
                  WebkitTextFillColor: "transparent",
                  backgroundClip: "text",
                }}
              >
                Proposals in Minutes
              </span>
            </h1>

            <p
              style={{
                fontSize: "clamp(1.1rem, 2vw, 1.4rem)",
                color: "rgba(255, 255, 255, 0.7)",
                marginBottom: "50px",
                lineHeight: "1.8",
                letterSpacing: "-0.3px",
                fontWeight: "400",
              }}
            >
              ASSEMBLE은 사용자의 요청사항에 맞게
              <br />
              AI 기반 인테리어를 추천합니다
            </p>

            <div style={{ display: "flex", gap: "20px", flexWrap: "wrap" }}>
              <motion.button
                style={{
                  padding: "20px 50px",
                  fontSize: "1.15rem",
                  fontWeight: 700,
                  border: "none",
                  borderRadius: "15px",
                  background: "linear-gradient(135deg, #ff6b35 0%, #ff4d00 100%)",
                  color: "#fff",
                  cursor: "pointer",
                  transition: "all 0.3s ease",
                  boxShadow: "0 10px 30px rgba(255, 107, 53, 0.4)",
                  letterSpacing: "-0.3px",
                }}
                whileHover={{
                  scale: 1.05,
                  boxShadow: "0 15px 40px rgba(255, 107, 53, 0.5)",
                }}
                whileTap={{ scale: 0.95 }}
              >
                Get Started
              </motion.button>

              <motion.button
                style={{
                  padding: "20px 50px",
                  fontSize: "1.15rem",
                  fontWeight: 700,
                  border: "2px solid rgba(255, 255, 255, 0.2)",
                  borderRadius: "15px",
                  background: "rgba(255, 255, 255, 0.05)",
                  backdropFilter: "blur(10px)",
                  color: "#fff",
                  cursor: "pointer",
                  transition: "all 0.3s ease",
                  letterSpacing: "-0.3px",
                }}
                whileHover={{
                  background: "rgba(255, 255, 255, 0.1)",
                  borderColor: "rgba(255, 255, 255, 0.3)",
                }}
                whileTap={{ scale: 0.95 }}
              >
                Learn More
              </motion.button>
            </div>
          </motion.div>

          {/* Right Image */}
          <motion.div
            variants={fadeUp}
            style={{
              borderRadius: "24px",
              overflow: "hidden",
              boxShadow:
                "0 30px 90px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(255, 255, 255, 0.08)",
              position: "relative",
            }}
          >
            <div
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                background:
                  "linear-gradient(135deg, rgba(255, 107, 53, 0.15) 0%, transparent 100%)",
                zIndex: 1,
              }}
            />
            <img
              src="https://image.hanssem.com/hsimg/upload/homeIdea/2025/10/15/1760508599558_057278.jpg?w=1500"
              alt="Interior Design"
              style={{
                width: "100%",
                height: "700px",
                objectFit: "cover",
                display: "block",
              }}
            />
          </motion.div>
        </motion.div>

        {/* Features & Stats Section은 그대로 유지 */}
        {/* ... 아래 기존 코드 그대로 둬도 됨 */}
      </main>
    </div>
  );
}

export default Hero;
